_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("triplet_margin_loss_kernel")

class ModelNew(nn.Module):
    """
    A model that computes Triplet Margin Loss for metric learning tasks,
    using a single custom PTX kernel for the entire computation.
    """
    def __init__(self, margin=1.0):
        super(ModelNew, self).__init__()
        self.margin = float(margin)

    def forward(self, anchor, positive, negative):
        batch_size, feature_dim = anchor.shape[0], anchor.shape[1]
        # Allocate the scalar accumulator uninitialized and zero it using the
        # kernel's own lightweight MODE_ZERO path instead of dispatching a
        # separate generic PyTorch elementwise fill kernel. The generic fill
        # kernel launch was flagged by profiling as severely underutilizing
        # the device (single block, ~8% achieved occupancy) purely due to
        # host-side dispatch/launch overhead for a 1-element tensor. Reusing
        # the already-present MODE_ZERO branch keeps this a minimal, tightly
        # scoped custom launch instead.
        output = torch.empty((), dtype=torch.float32, device=anchor.device)
        module = _get_ptx_module()
        stream = torch.cuda.current_stream(anchor.device)
        module.launch(
            "triplet_margin_loss_kernel",
            grid=(1, 1, 1),
            block=(32, 1, 1),
            arguments=[
                anchor,
                positive,
                negative,
                output,
                u32(batch_size),
                u32(feature_dim),
                f32(self.margin),
                u32(0),
            ],
            shared_memory=0,
            stream=stream,
        )
        # Compute per-row triplet loss and accumulate the mean.
        module.launch(
            "triplet_margin_loss_kernel",
            grid=(batch_size, 1, 1),
            block=(256, 1, 1),
            arguments=[
                anchor,
                positive,
                negative,
                output,
                u32(batch_size),
                u32(feature_dim),
                f32(self.margin),
                u32(1),
            ],
            shared_memory=0,
            stream=stream,
        )
        return output

